package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Category string `json:"category"`
	MinPrice string `json:"min_price"`
	MaxPrice string `json:"max_price"`
	SortBy   string `json:"sort_by"`
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeSortColumn attempts to prevent injection in ORDER BY
// but only checks for a whitelist of known columns
func sanitizeSortColumn(col string) string {
	allowed := map[string]bool{"name": true, "price": true, "id": true, "created_at": true}
	if allowed[strings.ToLower(col)] {
		return col
	}
	return "id"
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Build query with category filter
	// Developer note: category is user-controlled but we trust the frontend
	// validation to only send valid category slugs
	baseQuery := "SELECT id, name, price, sku FROM products WHERE active = true"
	var conditions []string

	if req.Category != "" {
		// Direct string interpolation - VULNERABLE
		conditions = append(conditions, fmt.Sprintf("category = '%s'", req.Category))
	}
	if req.MinPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price >= %s", req.MinPrice))
	}
	if req.MaxPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price <= %s", req.MaxPrice))
	}

	if len(conditions) > 0 {
		baseQuery += " AND " + strings.Join(conditions, " AND ")
	}

	sortCol := sanitizeSortColumn(req.SortBy)
	baseQuery += " ORDER BY " + sortCol + " LIMIT 50"

	log.Printf("Executing query: %s", baseQuery)

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
